package com.example.familytree.service;

import com.example.familytree.config.AppProperties;
import com.example.familytree.domain.DomainModels.*;
import com.example.familytree.repo.Repositories.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.transaction.Transactional;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.io.*;
import java.util.zip.*;

@Service
public class WorkflowService {
 private final AccessService access; private final SuggestionRepo suggestions; private final StoryRepo stories; private final EventRepo events; private final NotificationRepo notifications; private final TransferJobRepo transfers; private final BackupRepo backups; private final OcrRepo ocr; private final MemberRepo members; private final RelationRepo relations; private final MediaRepo media; private final ObjectMapper json; private final AppProperties props; private final JdbcClient jdbc;
 public WorkflowService(AccessService a,SuggestionRepo s,StoryRepo st,EventRepo e,NotificationRepo n,TransferJobRepo t,BackupRepo b,OcrRepo o,MemberRepo m,RelationRepo r,MediaRepo md,ObjectMapper j,AppProperties p,JdbcClient jdbc){access=a;suggestions=s;stories=st;events=e;notifications=n;transfers=t;backups=b;ocr=o;members=m;relations=r;media=md;json=j;props=p;this.jdbc=jdbc;}
 public Suggestion suggest(Long tree,String targetType,Long targetId,Map<String,Object> payload,Authentication a)throws Exception{access.requireEdit(tree,a);if("MEMBER".equals(targetType))requireTreeMember(tree,targetId);var s=new Suggestion();s.setTreeId(tree);s.setSubmitterId(access.current(a).getId());s.setTargetType(targetType);s.setTargetId(targetId);s.setPayloadJson(json.writeValueAsString(payload));s.setStatus(Status.PENDING);return suggestions.save(s);}
 public List<Suggestion> pending(Long tree,Authentication a){access.requireEdit(tree,a);return suggestions.findByTreeIdAndStatus(tree,Status.PENDING);}
 @Transactional public Suggestion review(Long tree,Long id,boolean approve,String comment,Authentication a)throws Exception{access.requireEdit(tree,a);var s=suggestions.findById(id).filter(x->x.getTreeId().equals(tree)).orElseThrow(()->new AccessService.NotFoundException("建议不存在"));if(s.getStatus()!=Status.PENDING)throw new AccessService.ConflictException("建议已审核");if(approve&&"MEMBER".equals(s.getTargetType())&&s.getTargetId()!=null){var m=members.findByIdAndTreeIdAndDeletedFalse(s.getTargetId(),tree).orElseThrow();var p=json.readValue(s.getPayloadJson(),Map.class);if(p.containsKey("name"))m.setName(String.valueOf(p.get("name")));if(p.containsKey("notes"))m.setNotes(String.valueOf(p.get("notes")));members.save(m);}s.setStatus(approve?Status.APPROVED:Status.REJECTED);s.setReviewerId(access.current(a).getId());s.setReviewComment(comment);s.setReviewedAt(Instant.now());return suggestions.save(s);}
 public Story saveStory(Long tree,Story s,Authentication a){access.requireEdit(tree,a);requireTreeMember(tree,s.getMemberId());s.setId(null);s.setTreeId(tree);s.setAuthorId(access.current(a).getId());return stories.save(s);}
 public List<Story> stories(Long tree,Authentication a){access.requireRead(tree,a);return stories.findByTreeId(tree);}
 public FamilyEvent saveEvent(Long tree,FamilyEvent e,Authentication a){access.requireEdit(tree,a);requireTreeMember(tree,e.getMemberId());e.setId(null);e.setTreeId(tree);e.setCreatedBy(access.current(a).getId());return events.save(e);}
 public List<FamilyEvent> events(Long tree,Authentication a){access.requireRead(tree,a);return events.findByTreeId(tree);}
 public List<Notification> notifications(Authentication a){return notifications.findByUserIdOrderByCreatedAtDesc(access.current(a).getId());}
 public Notification readNotification(Long id,Authentication a){var u=access.current(a);var n=notifications.findById(id).filter(x->x.getUserId().equals(u.getId())).orElseThrow();n.setReadAt(Instant.now());return notifications.save(n);}
 public TransferJob exportTree(Long tree,String format,Authentication a)throws Exception{access.requireEdit(tree,a);var u=access.current(a);var job=new TransferJob();job.setTreeId(tree);job.setUserId(u.getId());job.setDirection("EXPORT");job.setFormat(format.toUpperCase());job.setStatus(Status.RUNNING);job=transfers.save(job);try{byte[] bytes=exportBytes(tree,job.getFormat());var root=Path.of(props.storageRoot()).toAbsolutePath().normalize().resolve("exports");Files.createDirectories(root);var path=root.resolve(job.getId()+"."+extension(job.getFormat())).normalize();Files.write(path,bytes);job.setResultPath(path.toString());job.setStatus(Status.COMPLETED);job.setFinishedAt(Instant.now());}catch(Exception ex){job.setStatus(Status.FAILED);job.setErrorMessage(ex.getMessage());job.setFinishedAt(Instant.now());}return transfers.save(job);}
 public byte[] exportBytes(Long tree,String format)throws Exception{var ms=members.findByTreeIdAndDeletedFalse(tree);return switch(format.toUpperCase()){case "JSON"->json.writerWithDefaultPrettyPrinter().writeValueAsBytes(Map.of("members",ms,"relationships",relations.findAll().stream().filter(r->r.getTreeId().equals(tree)).toList()));case "GEDCOM"->gedcom(ms).getBytes(StandardCharsets.UTF_8);case "CSV","CSV_ZIP"->csvZip(ms);default->throw new AccessService.BadRequestException("格式仅支持 JSON/GEDCOM/CSV_ZIP");};}
 public TransferJob importData(Long tree,String format,byte[] bytes,Authentication a)throws Exception{access.requireEdit(tree,a);var j=new TransferJob();j.setTreeId(tree);j.setUserId(access.current(a).getId());j.setDirection("IMPORT");j.setFormat(format.toUpperCase());j.setStatus(Status.RUNNING);j=transfers.save(j);try{switch(j.getFormat()){case "JSON"->importJson(tree,bytes);case "GEDCOM"->importGedcom(tree,new String(bytes,StandardCharsets.UTF_8));case "CSV","CSV_ZIP"->importCsv(tree,new String(unzipFirst(bytes),StandardCharsets.UTF_8));default->throw new AccessService.BadRequestException("不支持的导入格式");}j.setStatus(Status.COMPLETED);}catch(Exception e){j.setStatus(Status.FAILED);j.setErrorMessage(e.getMessage());}j.setFinishedAt(Instant.now());return transfers.save(j);}
 public BackupRecord backup(Long tree,Authentication a)throws Exception{access.requireEdit(tree,a);var bytes=exportBytes(tree,"JSON");var root=Path.of(props.storageRoot()).toAbsolutePath().normalize().resolve("backups");Files.createDirectories(root);var path=root.resolve(tree+"-"+UUID.randomUUID()+".json");Files.write(path,bytes);var b=new BackupRecord();b.setTreeId(tree);b.setCreatedBy(access.current(a).getId());b.setStoredPath(path.toString());b.setSizeBytes(bytes.length);return backups.save(b);}
 public List<BackupRecord> backups(Long tree,Authentication a){access.requireRead(tree,a);return backups.findByTreeIdOrderByCreatedAtDesc(tree);}
 public Path backupPath(Long tree,Long id,Authentication a){access.requireRead(tree,a);var b=backups.findById(id).filter(x->x.getTreeId().equals(tree)).orElseThrow();var p=Path.of(b.getStoredPath()).toAbsolutePath().normalize();if(!Files.isRegularFile(p))throw new AccessService.NotFoundException("备份文件不存在");return p;}
 public OcrJob startOcr(Long tree,Long mediaId,String provider,Authentication a){access.requireEdit(tree,a);if(props.ocr()==null||!props.ocr().enabled())throw new AccessService.ConflictException("OCR 功能未启用");media.findByIdAndTreeId(mediaId,tree).orElseThrow();var configured=props.ocr().provider();var selected=provider==null||provider.isBlank()?configured:provider;if(selected==null||selected.isBlank()||"disabled".equalsIgnoreCase(selected))throw new AccessService.ConflictException("OCR Provider 未配置");var o=new OcrJob();o.setTreeId(tree);o.setMediaId(mediaId);o.setRequestedBy(access.current(a).getId());o.setProvider(selected);o.setStatus(Status.PENDING);o.setRawText("");o.setCorrectedText("");return ocr.save(o);}
 public OcrJob correctOcr(Long tree,Long id,String corrected,Map<String,Object> draft,Authentication a)throws Exception{access.requireEdit(tree,a);var o=ocr.findById(id).filter(x->x.getTreeId().equals(tree)).orElseThrow();o.setCorrectedText(corrected);o.setDraftMemberJson(json.writeValueAsString(draft));return ocr.save(o);}
 public Map<String,Object> audit(Long tree,Authentication a){access.requireEdit(tree,a);var rows=jdbc.sql("select id,user_id,action,entity_type,entity_id,created_at from audit_logs where tree_id=:t order by created_at desc limit 200").param("t",tree).query().listOfRows();return Map.of("items",rows);}
 public Map<String,Object> search(Long tree,String query,Authentication a){access.requireRead(tree,a);String q=query==null?"":query.trim().toLowerCase();var matched=members.findByTreeIdAndDeletedFalse(tree).stream().filter(m->m.getName().toLowerCase().contains(q)||(m.getOccupation()!=null&&m.getOccupation().toLowerCase().contains(q))||(m.getBirthPlace()!=null&&m.getBirthPlace().toLowerCase().contains(q))).toList();return Map.of("query",q,"members",matched,"count",matched.size());}
 private void requireTreeMember(Long tree,Long member){if(member!=null)members.findByIdAndTreeIdAndDeletedFalse(member,tree).orElseThrow(()->new AccessService.NotFoundException("成员不存在"));}
 private String gedcom(List<Member> ms){var b=new StringBuilder("0 HEAD\n1 GEDC\n2 VERS 5.5.1\n1 CHAR UTF-8\n");for(var m:ms)b.append("0 @I").append(m.getId()).append("@ INDI\n1 NAME ").append(m.getName()).append("\n1 SEX ").append(m.getGender()==Gender.MALE?"M":m.getGender()==Gender.FEMALE?"F":"U").append("\n");return b.append("0 TRLR\n").toString();}
 private String csv(List<Member> ms){var b=new StringBuilder("id,name,gender,birthDate,birthPlace,deathDate,occupation,address\n");for(var m:ms)b.append(m.getId()).append(',').append(q(m.getName())).append(',').append(m.getGender()).append(',').append(q(m.getBirthDate())).append(',').append(q(m.getBirthPlace())).append(',').append(q(m.getDeathDate())).append(',').append(q(m.getOccupation())).append(',').append(q(m.getAddress())).append('\n');return b.toString();}
 private byte[] csvZip(List<Member> ms)throws Exception{var out=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(out,StandardCharsets.UTF_8)){zip.putNextEntry(new ZipEntry("members.csv"));zip.write(csv(ms).getBytes(StandardCharsets.UTF_8));zip.closeEntry();}return out.toByteArray();}
 private byte[] unzipFirst(byte[] b)throws Exception{try(var z=new ZipInputStream(new ByteArrayInputStream(b),StandardCharsets.UTF_8)){if(z.getNextEntry()==null)throw new AccessService.BadRequestException("空 ZIP");return z.readAllBytes();}}
 @SuppressWarnings("unchecked") private void importJson(Long tree,byte[] b)throws Exception{var root=json.readValue(b,Map.class);for(var x:(List<Map<String,Object>>)root.getOrDefault("members",List.of())){var name=String.valueOf(x.get("name"));if(!name.isBlank())members.save(new Member(tree,name,Gender.valueOf(String.valueOf(x.getOrDefault("gender","UNKNOWN")))));}}
 private void importGedcom(Long tree,String text){String name=null;for(String line:text.split("\\R")){if(line.startsWith("1 NAME "))name=line.substring(7).trim();else if(name!=null&&line.startsWith("0 ")){members.save(new Member(tree,name,Gender.UNKNOWN));name=null;}}if(name!=null)members.save(new Member(tree,name,Gender.UNKNOWN));}
 private void importCsv(Long tree,String text){var lines=text.split("\\R");for(int i=1;i<lines.length;i++){var c=lines[i].split(",",-1);if(c.length>1){var name=c[1].replaceAll("^\"|\"$","").replace("\"\"","\"");if(!name.isBlank())members.save(new Member(tree,name,Gender.UNKNOWN));}}}
 private String q(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";} private String extension(String f){return switch(f){case"JSON"->"json";case"GEDCOM"->"ged";default->"zip";};}
}
